using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns localized name of the Telegram support user; for Telegram support only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Text> GetSupportNameAsync()
    {

           using var activity =  StartCallActivity("GetSupportNameAsync", typeof(GetSupportName).FullName ?? "GetSupportNameAsync");

           try
           {
             return client.GetSupportNameAsync();
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
